def test_subclasses_do_not_affect_the_base_class_if_no_DBC(self) -> None:
    # NOTE (mristin):
    # This is a regression test for:
    # https://github.com/Parquery/icontract/issues/295
    #
    # where the invariants of the derived class erroneously "slipped into"
    # the base class when DBC or DBCMeta were not set in the ``Base`` class.
    # This bug has been fixed - invariants should be class-specific.

    @icontract.invariant(lambda: True)
    class Base:
        def __repr__(self) -> str:
            return "an instance of {}".format(self.__class__.__name__)

    # Derived class with a failing invariant
    @icontract.invariant(lambda: False)
    class Derived(Base):  # pylint: disable=unused-variable
        pass

    # Base class instantiation should succeed since only Base's invariant (True) is checked
    base_instance = Base()
    self.assertIsInstance(base_instance, Base)

    # Derived class instantiation should fail since Derived's invariant (False) is checked
    violation_error = None  # type: Optional[icontract.ViolationError]
    try:
        _ = Derived()
    except icontract.ViolationError as err:
        violation_error = err

    self.assertIsNotNone(violation_error)
    self.assertEqual(
        textwrap.dedent("""False: self was an instance of Derived"""),
        tests.error.wo_mandatory_location(str(violation_error)),
    )

