def _stripws_parenthesis(self, tlist):
    while tlist.tokens[1].is_whitespace:
        tlist.tokens.pop(1)

    # Remove trailing whitespace before closing parenthesis
    # Only remove whitespace that comes after all semantic content
    # Find the last non-whitespace, non-closing-paren token
    last_content_idx = None
    for i in range(len(tlist.tokens) - 2, 0, -1):  # Go backwards from second to last
        if not tlist.tokens[i].is_whitespace:
            last_content_idx = i
            break

    # Remove whitespace tokens that come after the last content token
    if last_content_idx is not None:
        i = len(tlist.tokens) - 2  # Start from second to last token
        while i > last_content_idx:
            if tlist.tokens[i].is_whitespace:
                tlist.tokens.pop(i)
            i -= 1

    self._stripws_default(tlist)

